import java.nio.file.*;import jdk.internal.org.objectweb.asm.*;import jdk.internal.org.objectweb.asm.tree.*;import java.util.*;
public class PatchLanguage{public static void main(String[] args)throws Exception{Path root=Path.of(args[0]);Set<String> words=new HashSet<>();for(String line:Files.readAllLines(Path.of(args[1])))words.add(line.split("\t",-1)[0]);int edits=0;try(var files=Files.walk(root)){for(Path p:files.filter(f->f.toString().endsWith(".class")).toList()){ClassNode c=new ClassNode();new ClassReader(Files.readAllBytes(p)).accept(c,0);if(!c.name.startsWith("dev/zomboid/mts/")||c.name.endsWith("WorkshopLanguage"))continue;int count=0;for(MethodNode m:c.methods){for(AbstractInsnNode ins:m.instructions.toArray())if(ins instanceof LdcInsnNode l&&l.cst instanceof String s&&words.contains(s)){m.instructions.insert(ins,new MethodInsnNode(Opcodes.INVOKESTATIC,"dev/zomboid/mts/WorkshopLanguage","text","(Ljava/lang/String;)Ljava/lang/String;",false));count++;}if(c.name.equals("dev/zomboid/mts/R")&&m.name.equals("set")){InsnList inject=new InsnList();inject.add(new VarInsnNode(Opcodes.ALOAD,1));inject.add(new VarInsnNode(Opcodes.ALOAD,2));inject.add(new MethodInsnNode(Opcodes.INVOKESTATIC,"dev/zomboid/mts/WorkshopLanguage","displayed","(Ljava/lang/String;Ljava/lang/Object;)Ljava/lang/Object;",false));inject.add(new VarInsnNode(Opcodes.ASTORE,2));m.instructions.insert(inject);count++;}}if(count>0){ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);c.accept(w);Files.write(p,w.toByteArray());edits+=count;}}}System.out.println("Localized display hooks: "+edits);}}
